#include "../src/residual.hpp"
#include "io_dft.hpp"
#include "theta_all.hpp"
Poly load(fs::path p){std::ifstream f(p,std::ios::binary);int nr=read32(f),nc=read32(f);if(nr!=1)throw std::runtime_error("bad dimensions");f.close();return Poly(read_rows(p,nr,nc)[0]);}
int main(int argc,char**argv){try{if(argc<3)throw std::runtime_error("usage: gcd_analyze ROOT DIR");int root=std::stoi(argv[1]);std::string dir=argv[2];input::init();auto g=load(dir+"/gcd_72_73.bin");Poly p;p.c.resize(g.deg()/5+1);for(int i=0;i<=g.deg();i++)if(g[i]){if(i%5)throw std::runtime_error("not 5 power");p.c[i/5]=g[i].pow(78125);}if(frobenius_poly(p,5)!=g)throw std::runtime_error("fifthroot");write_rows(dir+"/gcd_radical_candidate.bin",Rows{p.c});auto sf=gcd(p,p.deriv());std::cout<<"fifthroot degree="<<p.deg()<<" derivative gcd="<<sf.deg()<<"\n";std::cout<<"root coefficients=";for(auto c:p.c)std::cout<<c<<",";std::cout<<"\n";std::cout<<"gcd theta="<<gcd(p,theta_for_root(root,F::code(64426))).deg()<<" H="<<gcd(p,Poly::mon(1)).deg()<<"\n";
 auto x=Poly::mon(1),y=x;for(int n=1;n<=9;n++){y=y.powmod(kfield::ORDER,p);auto a=gcd(p,y-x);std::cout<<"roots in K^"<<n<<": factor degree="<<a.deg()<<"\n";}
 for(int n=71;n<=77;n++){fs::path path=dir+"/E"+std::to_string(n)+".bin";std::ifstream f(path,std::ios::binary);int nr=read32(f),nc=read32(f);f.close();auto R=read_rows(path,nr,nc);int deg=-1;for(int j=0;j<nc;j++){Poly a;for(auto row:R)a.c.push_back(row[j]);a.trim();if(a%p)deg=j;}std::cout<<"E"<<n<<" degree in mu after p reduction="<<deg<<"\n";}
 std::ofstream meta(dir+"/radical_summary.json");meta<<"{\"gcd_degree\":"<<g.deg()<<",\"fifth_root_degree\":"<<p.deg()<<",\"exact_fifth_power_verified\":true,\"squarefree\":"<<(sf.deg()==0?"true":"false")<<"}\n";return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
